class SJISProber < Prober
  def initialize
    super
    @state = :detecting
    @char_position = 0
    @mbcs = MBCharSetProber.new
    @sjis = SJIS.new
    @last_char = 0
  end

  def reset
    super
    @state = :detecting
    @char_position = 0
    @mbcs.reset
    @sjis.reset
    @last_char = 0
  end

  def get_charset_name
    'SHIFT_JIS'
  end

  def feed(a_buf)
    a_buf.each_byte do |c|
      if @state == :detecting
        if @mbcs.feed(c) == :reliable
          @state = :found_it
          break
        end
      end
      @last_char = c
      @char_position += 1
    end
    @state
  end

  def get_confidence
    if @state == :found_it
      @mbcs.get_confidence
    else
      0.0
    end
  end
end

