func Netstat() []*model.MetricValue {
	metrics := make([]*model.MetricValue, 0)

	// Read netstat data from kernel
	stats, err := nux.Netstat()
	if err != nil {
		log.Println("Error reading netstat data:", err)
		return metrics
	}

	// Process each netstat metric
	for key, value := range stats {
		if _, exists := USES[key]; !exists {
			continue
		}

		metric := model.MetricValue{
			Endpoint:   model.HostName,
			CounterType: model.COUNTER,
			Metric:     "netstat." + key,
			Value:      float64(value),
			Tags:       "",
			Timestamp:  model.Now(),
		}

		metrics = append(metrics, &metric)
	}

	return metrics
}

