	c.Lock()
	store := c.localStore
	if kvObject.Global() {
		store = c.globalStore
	}
	c.Unlock()

	if err := store.Put(kvObject); err != nil {
		return fmt.Errorf("failed to store object %s: %v", kvObject.Key(), err)
	}

	return nil
}

