	for i, part := range key {
		if i > 0 {
			buf.WriteByte(',')
		}
		switch v := part.(type) {
		case string, []byte, NullString:
			buf.WriteString(fmt.Sprintf("%q", v))
		case nil:
			buf.WriteString("null")
		default:
			buf.WriteString(fmt.Sprintf("%v", v))
		}
