func LoadDBConfig() (map[string]*DBConfig, error) {
	config := make(map[string]*DBConfig)
	iniFile := os.Getenv("FAYGO_CONFIG")
	if iniFile == "" {
		iniFile = DBCONFIG_FILE
	}
	if _, err := os.Stat(iniFile); os.IsNotExist(err) {
		return config, nil
	}
	err := ini.Load(iniFile, &config)
	if err != nil {
		return nil, err
	}
	// Set default values for missing fields
	for name, dbConf := range config {
		if dbConf.Name == "" {
			dbConf.Name = name
		}
		if dbConf.MaxOpenConns == 0 {
			dbConf.MaxOpenConns = 10
		}
		if dbConf.MaxIdleConns == 0 {
			dbConf.MaxIdleConns = 5
		}
		if dbConf.StructTag == "" {
			dbConf.StructTag = "db"
		}
	}
	return config, nil
}

