// LoadDBConfig loads database configuration from file
func LoadDBConfig() (map[string]*DBConfig, error) {
	configs := make(map[string]*DBConfig)

	// Load ini file
	iniFile := filepath.Join(faygo.CONFIG_DIR, "sqlx.ini")
	if _, err := os.Stat(iniFile); os.IsNotExist(err) {
		return configs, nil
	}

	// Parse ini file
	iniConfig, err := ini.Load(iniFile)
	if err != nil {
		return nil, err
	}

	// Iterate over sections (database names)
	for _, section := range iniConfig.Sections() {
		if section.Name() == "default" {
			continue
		}

