var (
	dbConfigs     = map[string]*DBConfig{}
	defaultConfig = &DBConfig{
		Name:         DEFAULTDB_NAME,
		Driver:       "mysql",
		Connstring:   "root:@tcp(127.0.0.1:3306)/faygo?charset=utf8",
		MaxOpenConns: 100,
		MaxIdleConns: 100,
		ColumnSnake:  true,
		StructTag:    "db",
	}
)

func loadDBConfig() error {
	var cfg *ini.File
	var err error
	var exist bool
	cfg, err = ini.Load(DBCONFIG_FILE)
	if err != nil {
		os.MkdirAll(filepath.Dir(DBCONFIG_FILE), 0777)
		cfg, err = ini.LooseLoad(DBCONFIG_FILE)
		if err != nil {
			return err
		}
	} else {
		exist = true
	}
	var hadDefaultConfig bool
	for _, section := range cfg.Sections() {
		if section.Name() == ini.DEFAULT_SECTION {
			continue
		}
		var dbConfig *DBConfig
		if section.Name() == DEFAULTDB_NAME {
			dbConfig = defaultConfig
			hadDefaultConfig = true
		} else {
			dbConfig = &DBConfig{Name: section.Name()}
		}
		err := section.MapTo(dbConfig)
		if err != nil {
			return err
		}
		dbConfigs[dbConfig.Name] = dbConfig
	}
	if !exist {
		sec, _ := cfg.NewSection(DEFAULTDB_NAME)
		defaultConfig.Enable = true
		err := sec.ReflectFrom(defaultConfig)
		if err != nil {
			return err
		}
		dbConfigs[DEFAULTDB_NAME] = defaultConfig
		return cfg.SaveTo(DBCONFIG_FILE)
	}
	if !hadDefaultConfig {
		*defaultConfig = DBConfig{}
	}
	return nil
}

generated_suffix:
func LoadDBConfig() map[string]*DBConfig {
	config := make(map[string]*DBConfig)
	ini.MustLoad(DBCONFIG_FILE, config)

	// Set defaults for each DBConfig
	for name, dbConfig := range config {
		if dbConfig.Name == "" {
			dbConfig.Name = name
		}
		if dbConfig.MaxOpenConns == 0 {
			dbConfig.MaxOpenConns = 10
		}
		if dbConfig.MaxIdleConns == 0 {
			dbConfig.MaxIdleConns = 5
		}
		if dbConfig.StructTag == "" {
			dbConfig.StructTag = "db"
		}
		if dbConfig.Driver == "" {
			faygo.Log.Fatal("Database driver is required in sqlx.ini for database: ", name)
		}
		if dbConfig.Connstring == "" {
			faygo.Log.Fatal("Database connstring is required in sqlx.ini for database: ", name)
		}
	}

	return config
}

func GetDBConfig(name string) *DBConfig {
	config := LoadDBConfig()
	if dbConfig, exists := config[name]; exists {
		return dbConfig
	}
	return nil
}

