func runDiffCmd(ctx *cli.Context) error {
	if len(ctx.Args()) != 2 {
		console.Fatalln("Please specify two arguments: FIRST and SECOND")
	}

	first := ctx.Args().Get(0)
	second := ctx.Args().Get(1)

	// Initialize the client
	client, err := newClient(first)
	if err != nil {
		return iodine.Wrap(err, "failed to initialize client for first argument")
	}

	// Initialize the second client
	client2, err := newClient(second)
	if err != nil {
		return iodine.Wrap(err, "failed to initialize client for second argument")
	}

	// Perform the diff operation
	diff, err := client.Diff(client2, first, second)
	if err != nil {
		return iodine.Wrap(err, "failed to compute differences")
	}

	// Output the differences
	if len(diff) == 0 {
		console.Println("No differences found.")
	} else {
		for _, d := range diff {
			console.Println(d)
		}
	}

	return nil
}

