func runDiffCmd(ctx *cli.Context) error {
	if len(ctx.Args()) != 2 {
		cli.ShowCommandHelpAndExit(ctx, "diff", 1)
	}

	first := ctx.Args().Get(0)
	second := ctx.Args().Get(1)

	// Initialize source and target objects
	src, err := newObject(first)
	if err != nil {
		return iodine.New(err, "failed to initialize source object: %s", first)
	}

	dst, err := newObject(second)
	if err != nil {
		return iodine.New(err, "failed to initialize target object: %s", second)
	}

	// Perform the diff operation
	diff, err := src.Diff(dst)
	if err != nil {
		return iodine.New(err, "failed to compute differences between %s and %s", first, second)
	}

	// Output the differences
	if len(diff) == 0 {
		console.Println("No differences found.")
		return nil
	}

	for _, d := range diff {
		console.Println(d)
	}

	return nil
}

