	network := c.Network()
	ones, bits := network.Mask.Size()

	size := 1<<uint(bits-ones) - 2
	min = ipToU32(dhcp4.IPAdd(network.IP, 1))
	max = ipToU32(dhcp4.IPAdd(network.IP, size))
	return min, max

}

func (c *Config) ipInRange(ip net.IP) bool {
	if ip == nil {
		return false
	}

	min, max := c.ipRange()
	uIP := ipToU32(ip)

	return uIP >= min && uIP <= max
}

