// AuthMiddleware validates the request's authorization header.
func AuthMiddleware() echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c echo.Context) error {
			authHeader := c.Request().Header.Get("Authorization")
			if authHeader == "" {
				return echo.NewHTTPError(401, "Authorization header is required")
			}

			// Expect "Bearer <token>"
			parts := strings.Split(authHeader, " ")
			if len(parts) != 2 || parts[0] != "Bearer" {
				return echo.NewHTTPError(401, "Invalid authorization format")
			}

			token := parts[1]
			user, err := store.GetUserByToken(token)
			if err != nil {
				log.WithError(err).Error("Failed to fetch user by token")
				return echo.NewHTTPError(401, "Invalid or expired token")
			}

			if user == nil {
				return echo.NewHTTPError(401, "User not found")
			}

			c.Set("user", user)
			return next(c)
		}
	}
}

