		for _, ans := range msg.answer {
			if ans.name == name && ans.qtype == qtype && ans.qclass == dnsClassINET {
				addrs = append(addrs, ans)
			}
			if ans.qtype == dnsTypeCNAME && ans.qclass == dnsClassINET {
				cname = ans.rdata
			}
		}

		if len(addrs) > 0 || cname != name {
			return cname, addrs, nil
		}
	}

	return "", nil, &DNSError{Error: "no such host", Name: name}
}

